  "test": "import pytest

from langfuse.api.score_configs.raw_client import RawScoreConfigsClient
from langfuse.api.commons.types.score_data_type import ScoreDataType


class DummyResponse:
    status_code = 200
    headers = {}
    text = ""

    def json(self):
        return {}


class DummyHttpxClient:
    def __init__(self):
        self.called = False

    def request(self, *args, **kwargs):
        self.called = True
        return DummyResponse()


class DummyWrapper:
    def __init__(self):
        self.httpx_client = DummyHttpxClient()


def test_create_name_length_validation():
    client = RawScoreConfigsClient(client_wrapper=DummyWrapper())
    # Name longer than 35 characters should raise ValueError
    long_name = "x" * 36
    with pytest.raises(ValueError):
        client.create(name=long_name, data_type=ScoreDataType.NUMERIC)

    # Valid name should not raise ValueError and should attempt the request
    client = RawScoreConfigsClient(client_wrapper=DummyWrapper())
    client.create(name="valid_name", data_type=ScoreDataType.NUMERIC)
    # ensure the request was actually called (no exception from request stub)
    assert client._client_wrapper.httpx_client.called
